import net.minecraftforge.fml.common.Mod;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Mod(value="fabric_data_attachment_api_v1")
public class AttachmentEntrypoint {
    public static final Logger LOGGER = LoggerFactory.getLogger((String)"fabric-data-attachment-api-v1");

    public AttachmentEntrypoint() {
        ServerPlayerEvents.COPY_FROM.register((oldPlayer, newPlayer, alive) -> AttachmentTargetImpl.transfer((AttachmentTarget)oldPlayer, (AttachmentTarget)newPlayer, !alive));
        ServerEntityWorldChangeEvents.AFTER_ENTITY_CHANGE_WORLD.register((originalEntity, newEntity, origin, destination) -> AttachmentTargetImpl.transfer((AttachmentTarget)originalEntity, (AttachmentTarget)newEntity, false));
        ServerLivingEntityEvents.MOB_CONVERSION.register((previous, converted, keepEquipment) -> AttachmentTargetImpl.transfer((AttachmentTarget)previous, (AttachmentTarget)converted, true));
    }
}

